function Q.buildPath()
Q.samples={}
local twb=H.PATH and H.PATH.PATH_CACHE and H.PATH.PATH_CACHE[workspace._BASES.pve]
if not twb then
return
end
for uwb,vwb in pairs(twb)do
if not(H.PATH.HIDDEN_MOCK_LANES and H.PATH.HIDDEN_MOCK_LANES[uwb.Name])then
local wwb={}
for xwb,ywb in ipairs(vwb.points or{})do
table.insert(wwb,ywb.part.Position)
end
local zwb=0
for Awb=2,#wwb do
zwb=zwb+(wwb[Awb]-wwb[Awb-1]).Magnitude
end
local Bwb=0
for Cwb=2,#wwb do
local Dwb,Ewb=wwb[Cwb-1],wwb[Cwb]
local Fwb=(Ewb-Dwb).Magnitude
local Gwb=math.max(1,math.floor(Fwb/2))
for Hwb=0,Gwb-1 do
local Iwb=Dwb:Lerp(Ewb,Hwb/Gwb)
table.insert(Q.samples,{pos=Iwb,prog=(Bwb+Fwb*Hwb/Gwb)/math.max(1,zwb),lane=uwb.Name})
end
Bwb=Bwb+Fwb
end
if wwb[#wwb]then
table.insert(Q.samples,{pos=wwb[#wwb],prog=1,lane=uwb.Name})
end
end
end
local Jwb,Kwb,Lwb={},0,0
for Mwb,Nwb in ipairs(Q.samples)do
local Owb=tostring(Nwb.lane)
if not Jwb[Owb]then
Kwb=Kwb+1
end
Jwb[Owb]=(Jwb[Owb]or 0)+1
Lwb=Lwb+1
end
Q.laneCount={n=Kwb,by=Jwb,avg=Kwb>0 and Lwb/Kwb or 1}
end
